begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('55555555-5555-4555-8555-555555555551','rating-a@example.invalid'),
 ('55555555-5555-4555-8555-555555555552','rating-b@example.invalid');
update rating_control set revision=0;
select ok((select relrowsecurity from pg_class where oid='skill_progress'::regclass),'Skill ratings have RLS');
select ok((select relrowsecurity from pg_class where oid='item_difficulty'::regclass),'Difficulty profiles have RLS');
select ok(not rating_state_valid('[]'),'Malformed rating state is rejected');
select ok(not rating_state_valid('{"rating":1500,"deviation":0,"volatility":0.06,"attempts":1,"updatedAt":0}'),'Zero uncertainty is rejected');
set local role service_role;
select append_learning_events('55555555-5555-4555-8555-555555555551','[{"id":"rating-db","kind":"lesson"}]');
select append_learning_events('55555555-5555-4555-8555-555555555552','[{"id":"rating-db","kind":"lesson"}]');
select is(jsonb_array_length(rating_pending('55555555-5555-4555-8555-555555555551',50)),1,'Pending queue is owner-filtered');
select is(rating_snapshot('55555555-5555-4555-8555-555555555551','[]')->>'revision','0','Snapshot carries an exact revision');
select throws_ok($$select commit_rating_period('55555555-5555-4555-8555-555555555551','rating-db','wrong',0,'{"skills":{},"buckets":{}}','no_evidence')$$,'P0001',null,'Changed source cannot be projected');
select is(commit_rating_period('55555555-5555-4555-8555-555555555551','rating-db',(select event_hash from learning_events where user_id='55555555-5555-4555-8555-555555555551'),5,'{"skills":{},"buckets":{}}','no_evidence'),'conflict','Stale shared snapshot is not committed');
select throws_ok($$select commit_rating_period('55555555-5555-4555-8555-555555555551','rating-db',(select event_hash from learning_events where user_id='55555555-5555-4555-8555-555555555551'),0,'{"skills":{"test.read":{"rating":1600,"deviation":100,"volatility":0.06,"attempts":1,"updatedAt":0}},"buckets":{"g2:1:test-db":{"rating":1400,"deviation":0,"volatility":0.06,"attempts":1,"updatedAt":0}}}','rated')$$,'P0001',null,'Invalid difficulty rolls back skill writes too');
select is((select count(*)::integer from skill_progress where user_id='55555555-5555-4555-8555-555555555551'),0,'Failed projection leaves no partial skill state');
select is((select revision from rating_control),0::bigint,'Failed projection leaves revision unchanged');
select is((select rating_version from learning_events where user_id='55555555-5555-4555-8555-555555555551'),null::integer,'Failed projection remains pending');
select is(commit_rating_period('55555555-5555-4555-8555-555555555551','rating-db',(select event_hash from learning_events where user_id='55555555-5555-4555-8555-555555555551'),0,'{"skills":{"test.read":{"rating":1600,"deviation":100,"volatility":0.06,"attempts":1,"updatedAt":0}},"buckets":{"g2:1:test-db":{"rating":1400,"deviation":100,"volatility":0.06,"attempts":1,"updatedAt":0}}}','rated'),'applied','Ratings and receipt commit together');
select is((select revision from rating_control),1::bigint,'Shared revision advances exactly once');
select is(commit_rating_period('55555555-5555-4555-8555-555555555551','rating-db',(select event_hash from learning_events where user_id='55555555-5555-4555-8555-555555555551'),0,'{"skills":{},"buckets":{}}','no_evidence'),'already','Duplicate projection is idempotent');
select is((select attempts from skill_progress where user_id='55555555-5555-4555-8555-555555555551'),1::bigint,'Duplicate projection cannot inflate evidence');
select is(jsonb_array_length(rating_pending('55555555-5555-4555-8555-555555555551',50)),0,'Committed receipt leaves the pending queue');
select is(commit_rating_period('55555555-5555-4555-8555-555555555552','rating-db',(select event_hash from learning_events where user_id='55555555-5555-4555-8555-555555555552'),1,'{"skills":{},"buckets":{}}','no_evidence'),'applied','Another owner with the same client ID is independent');
select is(commit_rating_period('55555555-5555-4555-8555-555555555552','missing','wrong',2,'{"skills":{},"buckets":{}}','no_evidence'),'missing','Missing source is not reconstructed');
set local role anon;
select throws_ok('select * from skill_progress','42501',null,'Guest cannot read ratings');
select throws_ok('select * from item_difficulty','42501',null,'Guest cannot read calibration data');
select throws_ok('select rating_pending(null,50)','42501',null,'Guest cannot read the projection queue');
set local role authenticated;
set local request.jwt.claims='{"sub":"55555555-5555-4555-8555-555555555551","role":"authenticated"}';
select is((select count(*)::integer from skill_progress),1,'Owner can read own skill rating');
select throws_ok('update skill_progress set rating=9999','42501',null,'Owner cannot write ratings');
select throws_ok('select rating_snapshot(null,''[]'')','42501',null,'Client cannot access another account snapshot');
select throws_ok('select commit_rating_period(null,''x'',''x'',0,''{}'',''rated'')','42501',null,'Client cannot invoke the rating writer');
select throws_ok('select * from rating_control','42501',null,'Calibration control is private');
set local request.jwt.claims='{"sub":"55555555-5555-4555-8555-555555555552","role":"authenticated"}';
select is((select count(*)::integer from skill_progress),0,'Other owner cannot read the skill rating');
reset role;
update rating_control set tau=0.6;
select is((select revision from rating_control),3::bigint,'Parameter changes invalidate in-flight snapshots');
delete from auth.users where id='55555555-5555-4555-8555-555555555551';
select is((select count(*)::integer from skill_progress where user_id='55555555-5555-4555-8555-555555555551'),0,'Account deletion cascades to personal ratings');
select is((select count(*)::integer from learning_events where user_id='55555555-5555-4555-8555-555555555551'),0,'Account deletion cascades to rating receipts');
select is((select attempts from item_difficulty where bucket_id='g2:1:test-db'),1::bigint,'Anonymous difficulty aggregate has no account reference');
select * from finish();
rollback;
